MAP
    NAME "SS_MAP_RURAL_BRECHA_EJIDAL"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE  'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_brecha_ejidal.log"
  	DEBUG 0

    LAYER
         PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_RURAL_BRECHA_EJIDAL"
        INCLUDE 'includes/conexion.map'
        DATA "gm_brecha_ejidal from public.l_brecha_ejidal using unique id_elemento_geografico using srid=32614"
        STATUS DEFAULT
        TYPE LINE
        CLASS
            NAME "Brecha Ejidal"
            STYLE
                COLOR 0 173 147
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP

